int main(){try{static_assert(sizeof(void*)==8,"x64 required");for(unsigned sequence=0;sequence<128;++sequence){RecoveredOwnedSceneCandidate scene;auto&a=scene.create({sequence*3+1,0,0,0});auto&b=scene.create({sequence*3+2,0,0,0});auto&c=scene.create({sequence*3+3,0,0,0});auto removedIdentity=b.identity;auto ah=a.record.handle,bh=b.record.handle,ch=c.record.handle;auto&ab=scene.attach(a,0x200f,{bh,bh});auto&bc=scene.attach(b,1,{ch});auto abtoken=ab.token,bctoken=bc.token;a.registration.state=0;unsigned observed=0,before=0,dirty=0;auto observe=[&](auto&){++observed;};auto mark=[&](auto&,uint32_t r){if(r!=3)throw std::runtime_error("request");++dirty;};auto prepare=[&](auto&){++before;};if(!scene.removeModeZero(bh,0,observe,mark,prepare))throw std::runtime_error("remove");if(scene.resolve(bh)||scene.attributes.resolve(bctoken)||scene.size()!=2||scene.mode!=1||observed!=1||before!=1||dirty!=2)throw std::runtime_error("removal state");if((ab.flags&0x4080)!=0x4080||a.registration.state!=3||scene.queues.registration.handles!=std::vector<uint32_t>{ah}||scene.queues.cache.handles!=std::vector<uint32_t>{ah})throw std::runtime_error("incoming invalidation");if(!scene.references.nodes.tokens(c.record).empty()||scene.references.nodes.allocationCount()!=0)throw std::runtime_error("dangling outgoing references");if(scene.references.live.find(removedIdentity,[&](uint32_t h)->const RecoveredPendingIdentityCandidate*{auto*p=scene.resolve(h);return p?&p->identity:nullptr;})!=0xffffffffu)throw std::runtime_error("stale identity");if(!scene.removeModeZero(ah,0,observe,mark,prepare)||!scene.removeModeZero(ch,0,observe,mark,prepare)||scene.size()||scene.attributes.size()||scene.references.handles.active()||scene.attributes.handles.active()||scene.references.nodes.allocationCount()||scene.attributes.resolve(abtoken))throw std::runtime_error("complete teardown");}std::cout<<"owned_scene_removal_sequences=128 actual_element_destructions=384"<<std::endl;return 0;}catch(const std::exception&e){std::cerr<<e.what()<<std::endl;return 1;}}
